  // 2. Find expired trials
  const sevenDaysAgo = new Date(Date.now() - 7 * 86400000).toISOString();
  const expiredUrl = SUPABASE_URL + '/rest/v1/alert_subscribers?plan=eq.trial&active=eq.true&trial_start=lt.' + sevenDaysAgo + '&select=phone,product';

  try {
    const expired = await http({ method: 'GET', url: expiredUrl, headers });
