    console.log('Expired trials:', list.length);

    const EVO_URL = 'http://148.230.90.171:8096';
    const EVO_KEY = 'wasapea-evo-key-2026';

    for (const sub of list) {
      // Deactivate
      const patchUrl = SUPABASE_URL + '/rest/v1/alert_subscribers?phone=eq.' + sub.phone + '&product=eq.' + sub.product;
      await http({
        method: 'PATCH',
        url: patchUrl,
        headers: { ...headers, 'Prefer': 'return=minimal' },
