          url: EVO_URL + '/message/sendText/wasapea-7c7a2c6c',
          headers: { 'apikey': EVO_KEY, 'Content-Type': 'application/json' },
          body: { number: sub.phone, text: msg }
        });
      } catch (err) {
        console.log('Send error for', sub.phone);
      }
    }
  } catch (err2) {
    console.log('Query error:', err2.message);
